# frozen_string_literal: true

module Hecks
  module Tools
    module Lanes
      # The workflow that watches each lane with an alert threshold: every hour it asks
      # `PromotionRun` whether the lane has stood behind the lane it follows for longer than its
      # `Lane` row allows. A late lane faults the run, and the fault files a finding, one a day: the
      # alert key carries the date, and the journal in Postgres lets the next hour see it.
      module WatchWorkflow
        HEADER = <<~YAML.chomp
          name: Watch lanes

          # Generated by hecks project_lanes from the Lane rows of the Vocabulary chapter. Do not hand-edit.
          #
          # Every hour, asks `PromotionRun` whether a lane has stood behind the lane it follows for
          # longer than its Lane row allows (`alert_after`, in hours). The rule is decided there, not
          # here. A late lane fails the run, files a finding (one a day) and asks Promote to try
          # again: a promotion that was dropped is picked up within the hour, and one that still
          # cannot go says why in its own run.
          on:
            schedule:
              - cron: "17 * * * *"
            workflow_dispatch: {}

          # One watch at a time; none is cancelled.
          concurrency:
            group: lane-watch
            cancel-in-progress: false

          permissions:
            contents: read
            checks: read
            issues: write
            actions: write

          jobs:
        YAML

        module_function

        # @param watched [Array<Hash{String => String}>] the lanes that have an alert threshold
        # @return [String] the workflow
        def text(watched)
          [HEADER, *watched.flat_map { |lane| job(lane["name"]) }].join("\n") << "\n"
        end

        # @param name [String] a watched lane's name
        # @return [Array<String>] the job that watches it
        def job(name)
          ["  watch_#{name}:", "    runs-on: ubuntu-latest", "    timeout-minutes: 10", "    steps:",
           *setup_steps, *watch_step(name), *retry_step(name)]
        end

        # A watch that fails found the lane late: the promotion that should have moved it may
        # have been dropped, so Promote is asked again. It judges the commits itself; this
        # decides nothing.
        def retry_step(name)
          ["      - name: Ask Promote to try #{name} again", "        if: failure()", "        env:",
           "          GH_TOKEN: ${{ github.token }}", "        run: gh workflow run promote.yml"]
        end

        def setup_steps
          ["      - uses: actions/checkout@v4", "        with:",
           "          # Full history: the lag is read from the commits one lane has and the other lacks.",
           "          fetch-depth: 0",
           "      - uses: ./.github/actions/setup-ruby",
           "      - uses: ./.github/actions/hecks-environment", "        with:",
           "          database: ${{ secrets.HECKS_JOURNAL_DATABASE }}"]
        end

        def watch_step(name)
          ["      - name: Watch #{name}", "        env:", "          GH_TOKEN: ${{ github.token }}",
           "          HECKS_FINDINGS_REPO: ${{ github.repository }}", "        run: >-",
           "          bundle exec exe/hecks promotion_run.watch lane=#{name}",
           "          run=watch-#{name}-${{ github.run_id }}-${{ github.run_attempt }}",
           "          alert_key=#{name}-lag-$(date -u +%Y-%m-%d) --wait"]
        end
      end
    end
  end
end
